// Перед прошивкой установите библиотеку "TM1637" (от Avishay Orpaz) через Менеджер библиотек
#include <Arduino.h>
#include <TM1637Display.h>

// Определение пинов для первого дисплея
#define CLK_1 2
#define DIO_1 3

// Определение пинов для второго дисплея
#define CLK_2 4
#define DIO_2 5

// Определение пинов для третьего дисплея
#define CLK_3 6
#define DIO_3 7

// Создаем три объекта дисплея
TM1637Display display1(CLK_1, DIO_1);
TM1637Display display2(CLK_2, DIO_2);
TM1637Display display3(CLK_3, DIO_3);

void setup() {
  // Устанавливаем яркость для каждого дисплея (от 0 до 7)
  display1.setBrightness(0x0f);
  display2.setBrightness(0x0f);
  display3.setBrightness(0x0f);

  // Очищаем экраны
  display1.clear();
  display2.clear();
  display3.clear();
}

void loop() {
  // Тест 1: Выводим разные числа на каждый экран
  display1.showNumberDec(1111);
  display2.showNumberDec(2222);
  display3.showNumberDec(3333);
  delay(2000);

  // Тест 2: Синхронно считаем от 0 до 9 на всех экранах
  for (int i = 0; i <= 9; i++) {
    display1.showNumberDec(i);
    display2.showNumberDec(i);
    display3.showNumberDec(i);
    delay(500);
  }

  // Очистка перед повтором цикла
  display1.clear();
  display2.clear();
  display3.clear();
  delay(1000);
}
